package com.pousadamarealta;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.pousadamarealta.dto.*;
import io.javalin.Javalin;
import io.javalin.testtools.JavalinTest;
import org.junit.jupiter.api.*;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

import static org.junit.jupiter.api.Assertions.*;

@Testcontainers
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class ReservationIntegrationTest {

    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:18")
        .withDatabaseName("testdb")
        .withUsername("test")
        .withPassword("test");

    private static Javalin app;
    private static final ObjectMapper objectMapper = new ObjectMapper().registerModule(new JavaTimeModule());
    private static final HttpClient httpClient = HttpClient.newHttpClient();
    private static int port;

    @BeforeAll
    static void setup() {
        System.setProperty("DB_URL", postgres.getJdbcUrl());
        System.setProperty("DB_USER", postgres.getUsername());
        System.setProperty("DB_PASSWORD", postgres.getPassword());
        System.setProperty("PORT", "0");

        app = createApp();
        port = app.port();
    }

    @AfterAll
    static void tearDown() {
        if (app != null) {
            app.stop();
        }
    }

    private static Javalin createApp() {
        String[] args = {};
        Main.main(args);
        return null;
    }

    @Test
    @Order(1)
    void shouldGetRooms() throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create("http://localhost:" + port + "/rooms"))
            .GET()
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());
        RoomDTO[] rooms = objectMapper.readValue(response.body(), RoomDTO[].class);
        assertEquals(5, rooms.length);
        assertEquals("101", rooms[0].getNumber());
        assertEquals("STANDARD", rooms[0].getType());
        assertEquals(2, rooms[0].getCapacity());
        assertEquals(249.90, rooms[0].getNightlyRate(), 0.01);
    }

    @Test
    @Order(2)
    void shouldCreateReservation() throws Exception {
        CreateReservationRequest request = new CreateReservationRequest();
        request.setRoomNumber("101");
        request.setGuestName("João Silva");
        request.setGuestEmail("joao@example.com");
        request.setGuestCpf("12345678901");
        request.setCheckIn("2027-03-10");
        request.setCheckOut("2027-03-12");
        request.setGuests(2);
        request.setRatePlan("STANDARD");

        String body = objectMapper.writeValueAsString(request);

        HttpRequest httpRequest = HttpRequest.newBuilder()
            .uri(URI.create("http://localhost:" + port + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(body))
            .build();

        HttpResponse<String> response = httpClient.send(httpRequest, HttpResponse.BodyHandlers.ofString());

        assertEquals(201, response.statusCode());
        ReservationDTO reservation = objectMapper.readValue(response.body(), ReservationDTO.class);
        assertNotNull(reservation.getId());
        assertEquals("101", reservation.getRoomNumber());
        assertEquals("PENDING", reservation.getStatus());
        assertEquals(2, reservation.getNights());
        assertEquals(499.80, reservation.getSubtotal(), 0.01);
        assertEquals(0.00, reservation.getDiscount(), 0.01);
        assertEquals(499.80, reservation.getTotal(), 0.01);
    }

    @Test
    @Order(3)
    void shouldCalculateHighSeasonPricing() throws Exception {
        CreateReservationRequest request = new CreateReservationRequest();
        request.setRoomNumber("102");
        request.setGuestName("Maria Santos");
        request.setGuestEmail("maria@example.com");
        request.setGuestCpf("98765432109");
        request.setCheckIn("2027-07-10");
        request.setCheckOut("2027-07-12");
        request.setGuests(2);
        request.setRatePlan("STANDARD");

        String body = objectMapper.writeValueAsString(request);

        HttpRequest httpRequest = HttpRequest.newBuilder()
            .uri(URI.create("http://localhost:" + port + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(body))
            .build();

        HttpResponse<String> response = httpClient.send(httpRequest, HttpResponse.BodyHandlers.ofString());

        assertEquals(201, response.statusCode());
        ReservationDTO reservation = objectMapper.readValue(response.body(), ReservationDTO.class);
        assertEquals(599.76, reservation.getSubtotal(), 0.01);
    }

    @Test
    @Order(4)
    void shouldApplyNonRefundableDiscount() throws Exception {
        CreateReservationRequest request = new CreateReservationRequest();
        request.setRoomNumber("201");
        request.setGuestName("Carla Dias");
        request.setGuestEmail("carla@example.com");
        request.setGuestCpf("11122233344");
        request.setCheckIn("2027-03-10");
        request.setCheckOut("2027-03-12");
        request.setGuests(2);
        request.setRatePlan("NON_REFUNDABLE");

        String body = objectMapper.writeValueAsString(request);

        HttpRequest httpRequest = HttpRequest.newBuilder()
            .uri(URI.create("http://localhost:" + port + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(body))
            .build();

        HttpResponse<String> response = httpClient.send(httpRequest, HttpResponse.BodyHandlers.ofString());

        assertEquals(201, response.statusCode());
        ReservationDTO reservation = objectMapper.readValue(response.body(), ReservationDTO.class);
        assertEquals(779.80, reservation.getSubtotal(), 0.01);
        assertEquals(116.97, reservation.getDiscount(), 0.01);
        assertEquals(662.83, reservation.getTotal(), 0.01);
    }

    @Test
    @Order(5)
    void shouldRejectOverCapacity() throws Exception {
        CreateReservationRequest request = new CreateReservationRequest();
        request.setRoomNumber("101");
        request.setGuestName("Pedro Costa");
        request.setGuestEmail("pedro@example.com");
        request.setGuestCpf("55566677788");
        request.setCheckIn("2027-04-01");
        request.setCheckOut("2027-04-02");
        request.setGuests(5);
        request.setRatePlan("STANDARD");

        String body = objectMapper.writeValueAsString(request);

        HttpRequest httpRequest = HttpRequest.newBuilder()
